import{_ as t,c as r,o as s,ah as i,j as e,a}from"./chunks/framework.oAolcYhj.js";const d="/Qonnectra-docs/pr-14/images/manual/teil-a/map.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/map_address_detail_select.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/map_opacity.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/map_legend_actions.jpg",m="/Qonnectra-docs/pr-14/images/manual/teil-a/map_selected_object.jpg",g="/Qonnectra-docs/pr-14/videos/map_attachment.webm",b="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search.jpg",p="/Qonnectra-docs/pr-14/images/manual/teil-a/map_search_flow.jpg",w=JSON.parse('{"title":"5. Karte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/05-karte.md","filePath":"manual/teil-a-anwenderhandbuch/05-karte.md"}'),k={name:"manual/teil-a-anwenderhandbuch/05-karte.md"};function f(S,n,_,z,K,A){return s(),r("div",null,[...n[0]||(n[0]=[i('<h1 id="_5-karte" tabindex="-1">5. Karte <a class="header-anchor" href="#_5-karte" aria-label="Permalink to &quot;5. Karte&quot;">​</a></h1><p>Die Karte ist eines der zentralen Werkzeuge in Qonnectra. Sie dient der visuellen Darstellung des Netzbestands, der Orientierung im Raum und dem schnellen Aufruf von Informationen zu einzelnen Netzobjekten. Sie erreichen die Karte über die linke Navigation durch Klicken auf den Menüpunkt „Karte“.</p><p><img src="'+d+'" alt="Screenshot Karte" data-zoomable="true"></p><h2 id="_5-1-bewegung-in-der-karte" tabindex="-1">5.1 Bewegung in der Karte <a class="header-anchor" href="#_5-1-bewegung-in-der-karte" aria-label="Permalink to &quot;5.1 Bewegung in der Karte&quot;">​</a></h2><p>Sie können in der Karte auf verschiedene Arten navigieren: Zoomen Sie mit dem Mausrad oder dem Touchpad hinein und heraus. Verschieben Sie den Kartenausschnitt mit gedrückter linker Maustaste.</p><p>Wenn Sie bei geöffneter Karte ein anderes Projekt auswählen, springt die Karte nicht automatisch in dessen Gebiet. Um dorthin zu gelangen, klicken Sie in der Legende oben rechts beim Eintrag „Adresse“ auf das Lupensymbol „Auf Ausdehnung zoomen“. Damit navigiert die Ansicht in den Bereich, in dem für dieses Projekt Daten vorhanden sind.</p><p class="img-row"><img src="'+l+'" alt="Screenshot Karte mit Hervorhebung des Layers Adresse in der Legende rechts oben" data-zoomable="true"><img src="'+o+'" alt="Screenshot Karte nach dem Zoom auf die Ausdehnung des Layers Adresse" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Qonnectra merkt sich den letzten Kartenausschnitt. Wenn Sie die Karte erneut öffnen, sehen Sie wieder die Stelle, an der Sie zuletzt gearbeitet haben.</p></div><h2 id="_5-2-anpassung-der-darstellung" tabindex="-1">5.2 Anpassung der Darstellung <a class="header-anchor" href="#_5-2-anpassung-der-darstellung" aria-label="Permalink to &quot;5.2 Anpassung der Darstellung&quot;">​</a></h2><p>Links unten in der Kartenansicht finden Sie den Regler „Transparenz“, mit dem Sie die <strong>Transparenz</strong> der Hintergrundkarte anpassen können. Dies ist hilfreich, um Netzdaten besser sichtbar zu machen.</p><p><img src="'+h+'" alt="Screenshot Karte mit Hervorhebung des Schiebereglers für die Transparenz der Karte" data-zoomable="true"></p><p>Auf der rechten Seite befindet sich die <strong>interaktive Legende</strong> („Layer“-Menü) mit den Einträgen „Adresse“, „Netzknoten“, „Trasse“, „Rohr“, „Gebiet“ und „OpenStreetMap“. Über die Symbole an den Einträgen können Sie:</p><ul><li>Objektarten (Layer) ein- oder ausblenden</li><li>Beschriftungen anzeigen oder verbergen</li><li>mit „Auf Ausdehnung zoomen“ die Ansicht auf alle Objekte eines Layers ausrichten</li><li>die Einträge „Netzknoten“ und „Gebiet“ über den kleinen Pfeil links aufklappen und die einzelnen Typen getrennt schalten</li><li>die Hintergrundkarte über den Eintrag „OpenStreetMap“ ausblenden oder in den Dunkelmodus wechseln</li></ul><p>Nicht jeder Eintrag bietet alle Möglichkeiten: Beim Eintrag „Rohr“ steht ausschließlich „Leitungsbeschriftungen anzeigen“ zur Verfügung. Mit dem Pfeil links neben „Layer“ klappen Sie die gesamte Liste ein, wenn Sie mehr von der Karte sehen möchten.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beschriftungen werden erst ab einer ausreichenden Zoomstufe eingeblendet. Wenn sich nach dem Einschalten nichts sichtbar ändert, zoomen Sie weiter in die Karte hinein.</p></div><p class="img-row"><img src="'+c+'" alt="Screenshot Karte mit Hervorhebung der Legende oben rechts" data-zoomable="true"><img src="'+u+'" alt="Vier Screenshots der Karte mit verschiedenen Einstellungen in der Legende" data-zoomable="true"></p><h2 id="_5-3-auswahl-von-objekten" tabindex="-1">5.3 Auswahl von Objekten <a class="header-anchor" href="#_5-3-auswahl-von-objekten" aria-label="Permalink to &quot;5.3 Auswahl von Objekten&quot;">​</a></h2><p>Wenn Sie ein Objekt (z. B. eine Trasse oder einen Netzknoten) auf der Karte anklicken, öffnet sich auf der rechten Seite eine Detailanzeige. Diese <strong>Info-Box</strong> überlagert die Karte, ohne den Kartenausschnitt zu verändern. Ihre Reiter stehen untereinander am linken Rand der Box und hängen von der Objektart ab:</p><ul><li>Trasse: „Eigenschaften“, „Rohrübersicht“, „Kabelübersicht“, „Aktionen“, „Anhänge“</li><li>Netzknoten und Adresse: „Eigenschaften“, „Aktionen“, „Anhänge“</li><li>Gebiet: „Eigenschaften“, „Anhänge“</li></ul><p>Die Angaben im Reiter „Eigenschaften“ sind nicht bearbeitbar, sondern dienen als Informationsquelle. Der Reiter „Rohrübersicht“ zeigt die Rohre der Trasse, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>, „Kabelübersicht“ die darin liegenden Kabel. Im Reiter „Aktionen“ finden Sie weiterführende Ansichten zum ausgewählten Objekt, etwa „Grabenprofil anzeigen“ bei einer Trasse oder „Struktur anzeigen“ bei einem Netzknoten. Bearbeiten können Sie ausschließlich den Reiter „Anhänge“, siehe Abschnitt <a href="#_5-3-1-anhange-von-kartenobjekten">Anhänge von Kartenobjekten</a>.</p><p>Ist die Info-Box zu schmal, ziehen Sie sie am linken Rand über den Griff „Größe der Seitenleiste ändern“ breiter. Schließen können Sie sie über das Kreuz „Seitenleiste schließen“ oben rechts in der Box. Ein Klick auf eine freie Stelle der Karte hebt die Auswahl ebenfalls auf – innerhalb eines Projektgebiets ist das allerdings kaum möglich, weil dessen Fläche die gesamte Umgebung überdeckt.</p><p><img src="'+m+'" alt="Screenshot Karte mit Hervorhebung eines ausgewählten Objekts und der Anzeige der Details in einer Info-Box rechts" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Wenn Sie ein Objekt über die Suche auswählen, öffnet sich die Info-Box <strong>nicht</strong>. Die Karte springt dann nur an die passende Stelle; klicken Sie das Objekt anschließend in der Karte an, um die Details zu sehen.</p></div><h3 id="_5-3-1-anhange-von-kartenobjekten" tabindex="-1">5.3.1 Anhänge von Kartenobjekten <a class="header-anchor" href="#_5-3-1-anhange-von-kartenobjekten" aria-label="Permalink to &quot;5.3.1 Anhänge von Kartenobjekten&quot;">​</a></h3><p>Zu jedem Kartenobjekt können Sie Dateien ablegen; der Reiter „Anhänge“ steht deshalb bei allen Objektarten zur Verfügung. Zum Hinzufügen klicken Sie im Bereich „Dateien hochladen“ auf „Dateien auswählen“ oder ziehen die Datei auf die Fläche „Dateien auswählen oder hierher ziehen“. Die maximale Dateigröße beträgt 50 MB.</p><p>Vorhandene Dateien stehen darunter im Bereich „Hochgeladene Dateien“, zusammengefasst in Ordnern, die nach ihrer Art benannt sind und die Anzahl enthalten, z. B. „documents (1)“. Klicken Sie auf einen Ordner, um ihn aufzuklappen – erst dann werden die einzelnen Dateien sichtbar. Zeigen Sie anschließend mit der Maus auf eine Datei, erscheinen rechts neben dem Dateinamen die Schaltflächen „Herunterladen“, „Umbenennen“ und „Datei löschen“; beim Löschen bestätigen Sie die Rückfrage.</p><p>Bei vielen Dateien hilft das Feld „Dateien suchen“ oberhalb der Liste. Sind die Schaltflächen nicht sichtbar, ist Ihr Fenster zu schmal: Scrollen Sie in der Info-Box nach rechts oder ziehen Sie die Box breiter.</p>',27),e("p",null,[e("video",{src:g,controls:"",playsinline:"",preload:"metadata"},[a(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/map_attachment.webm",download:""},"herunterladen"),a(" anstelle des Videos. ")])],-1),i('<h2 id="_5-4-suche" tabindex="-1">5.4 Suche <a class="header-anchor" href="#_5-4-suche" aria-label="Permalink to &quot;5.4 Suche&quot;">​</a></h2><p>Oben links befindet sich eine <strong>Suchfunktion</strong>. Hier können Sie gezielt nach Adressen, Netzknoten, Trassen, Rohren und Gebieten suchen.</p><p><img src="'+b+'" alt="Screenshot Karte mit Hervorhebung des Suchfeldes oben links" data-zoomable="true"></p><p>Dazu gehen Sie folgendermaßen vor:</p><ol><li>Geben Sie einen Begriff oder einen Teil davon in das Suchfeld ein.</li><li>Drücken Sie Enter oder klicken Sie auf das Lupensymbol.</li><li>Die Trefferliste öffnet sich direkt unterhalb des Suchfeldes; links oben steht die Anzahl der Treffer.</li><li>Jeder Treffer ist mit seiner Objektart gekennzeichnet, etwa „Adresse“, „Netzknoten“ oder „Trasse“.</li><li>Ab zehn Treffern erscheint im Kopf der Liste das Feld „Filtern“, mit dem Sie die Liste weiter einschränken.</li><li>Klicken Sie auf einen Treffer: Die Karte springt an die passende Stelle und das Objekt blinkt dreimal auf.</li></ol><p><img src="'+p+'" alt="Vier Screenshots des Suchablaufs in der Karte, nummeriert von 1 bis 6" data-zoomable="true"></p><p>Sollten Sie sich Details zu diesem Objekt anzeigen lassen wollen, klicken Sie auf das Objekt in der Karte (siehe <a href="#_5-3-auswahl-von-objekten">Auswahl von Objekten</a>).</p>',7)])])}const j=t(k,[["render",f]]);export{w as __pageData,j as default};
